<?php
/** Read-only deployed cohort/export reconciliation; uses existing identities and never creates grants or facts. */
use think\facade\Db;
function check($v,$label){if(!$v)throw new RuntimeException($label);}
function denied(callable $f){try{$f();return false;}catch(mohe\exceptions\AdminException $e){return true;}}
$access=new app\services\organization\PlatformStaffAccessServices();
$root=Db::name('system_admin')->where('status',1)->where('is_del',0)->where('level',0)->where('admin_type',0)->find();check($root,'ROOT_EXISTS');$access->assertAllowed((int)$root['id']);check(denied(fn()=>$access->assertAllowed(0)),'INVALID_ID_DENIED');
$menu=Db::name('system_menus')->where('unique_auth','setting-staff-index')->where('type',1)->where('is_del',0)->find();$parent=Db::name('system_menus')->where('unique_auth','admin-organizational-structure')->where('type',1)->where('is_del',0)->find();check($menu['menu_name']==='人员管理'&&$menu['pid']==$parent['id'],'MENU_PARENT');
$deniedId=null;foreach(Db::name('system_admin')->where('status',1)->where('is_del',0)->where('level','>',0)->where('admin_type',0)->select()->toArray()as$a){if(denied(fn()=>$access->assertAllowed((int)$a['id']))){$deniedId=(int)$a['id'];break;}}
$reflect=new ReflectionClass(app\controller\admin\v1\report\UnifiedReport::class);$c=$reflect->newInstanceWithoutConstructor();$p=$reflect->getProperty('adminId');$p->setAccessible(true);$p->setValue($c,$deniedId?:0);$svc=new app\services\report\EmployeeDashboardServices();check(denied(fn()=>$c->employeeDashboardPeople(new app\Request(),$svc)),'PEOPLE_ENDPOINT_DENIED');
$stores=array_map('intval',Db::name('system_store')->where('is_del',0)->column('id'));$range=['start'=>'2026-11-01','end'=>'2026-11-06'];$pop=new app\services\report\EmployeeDashboardPopulationServices();$active=$pop->active($stores,'',$range['end']);$beauty=$pop->active($stores,'美容师',$range['end']);check(count($pop->select($active,'beautician_count'))===count($beauty),'ACTUAL_JOB_NAME');
$ov=new ReflectionMethod($svc,'overview');$ov->setAccessible(true);$departures=$svc->people($stores,$range,['kind'=>'departures','role'=>'美容师'])['count'];$report=$ov->invoke($svc,$beauty,$range['end'],$departures);$checks=0;
foreach($report['cards']as$row)if(in_array($row['key'],['total','active_staff','beautician_count','departures'],true)){check($svc->people($stores,$range,['kind'=>$row['key'],'role'=>'美容师'])['count']===$row['value'],'CARD_'.$row['key']);$checks++;}
foreach(['education'=>'education','ages'=>'age','tenure'=>'tenure']as$section=>$kind)foreach($report[$section]as$i=>$row){check($svc->people($stores,$range,['kind'=>$kind,'bucket'=>(string)$i,'role'=>'美容师'])['count']===$row['value'],'BUCKET_'.$kind.'_'.$i);$checks++;}
check($svc->people([],$range,['kind'=>'total'])['count']===0,'EMPTY_SCOPE');
$req=app('request');$req->withGet(['page'=>1,'limit'=>50]);$req->adminId=(int)$root['id'];$req->adminInfo=$root;$req->setAction('index');$staff=app()->make(app\services\store\SystemStoreStaffServices::class);$ctrl=new app\controller\admin\v1\merchant\SystemStoreStaff(new think\facade\App(),$staff);$list=$ctrl->index()->getData();$export=$ctrl->exportList()->getData();check($list['status']===200&&$export['status']===200,'ACTUAL_CONTROLLER');$l=$list['data'];$x=$export['data'];check($l['count']===$x['count']&&count($l['list'])===count($x['export']),'LIST_EXPORT_COHORT');check(count($x['header'])===35,'EXPORT_35_COLUMNS');
if($l['list']){$ss=$l['list'][0];$d=app()->make(app\services\employee\EmployeePersonCompleteWriteServices::class)->getComplete((int)$ss['employee_id'],(int)$ss['id'],'hq',true);foreach(['staff_name','phone','avatar','account','education','id_card','join_date','birthday_date']as$k)check($x['export'][0][$k]===(string)($d[$k]??''),'EDITOR_'.$k);}
$member=new app\services\user\PlatformMemberAccessPolicy();$member->assertAllowed($root);$invalid=false;try{$member->assertAllowed([]);}catch(think\exception\ValidateException $e){$invalid=true;}check($invalid,'MEMBER_DENIAL');
echo json_encode(['result'=>'PASS','activeEmployees'=>count($active),'actualBeauticianEmployees'=>count($beauty),'cohortChecks'=>$checks,'exportColumns'=>count($x['header']),'listAndExportCount'=>$l['count'],'exportPageRows'=>count($x['export']),'deniedExistingIdentity'=>$deniedId,'menuParentCorrect'=>true,'editorFieldsReconciled'=>true,'memberPermissionPreserved'=>true,'businessWrites'=>false]);
